+                        var truncated = TakeUtf8Prefix(chunk, remaining);
+                        output.Append(truncated);
+                        chunkCallback?.Invoke(truncated);
+                    }
+
+                    onLimitExceeded();
+                    return new LimitedReadResult(output.ToString(), LimitExceeded: true);
