   158	            {
   159	                bindMounts.Add((m.HostPath, m.SandboxPath));
   160	            }
   161	        }
   162	
   163	        // Resolve timing context from the spec (null → no timing emitted).
   164	        var timingStore = _timings is not null && spec.TimingWorkItemId.HasValue ? _timings : null;
   165	        var timingItemId = spec.TimingWorkItemId.GetValueOrDefault();
   166	        var timingPhase = spec.TimingPhase ?? "work";
   167	
   168	        try
   169	        {
   170	            // Choose between two boot paths:
   171	            //   - Baseline-clone path (UseBaselineImages=true + profile is set):
   172	            //     bake one VM per profile lazily on first use, then `multipass
   173	            //     clone` from it for every subsequent sandbox. Pays the
   174	            //     install runcmd cost once per profile instead of per sandbox.
   175	            //   - Launch path (default): every VM goes through cloud-init.
   176	            //     Slower per VM but works without prior baking.
   177	            var useBaseline = _opts.UseBaselineImages
   178	                && !string.IsNullOrWhiteSpace(spec.Network.ProfileName);
   179	
   180	            // After this block the VM is in Stopped state, ready for native
   181	            // mounts. The launch path goes through a stop-mount-start cycle;
   182	            // the clone path skips the start (clone is born Stopped).
   183	            if (useBaseline)
   184	            {
   185	                var baselineName = await EnsureBaselineForProfileAsync(spec.Network.ProfileName!, spec.Flavor, ct);
   186	                await using var cloneScope = await TimingScope.BeginAsync(
   187	                    timingStore, timingItemId, timingPhase, "vm.clone", log: _log);
   188	                await CloneFromBaselineAsync(name, baselineName, ct);
   189	                // Clone is Stopped after `multipass clone`; no start yet.
   190	            }
   191	            else
   192	            {
   193	                var cloudInit = BuildCloudInit(_opts.ExtraRuncmd, _opts.ExtraCloudInit, spec.Flavor);
   194	                var cloudInitPath = Path.Combine(sandboxRoot, "cloud-init.yaml");
   195	                await File.WriteAllTextAsync(cloudInitPath, cloudInit, ct);
   196	                await using (var launchScope = await TimingScope.BeginAsync(
   197	                    timingStore, timingItemId, timingPhase, "vm.launch", log: _log))
   198	                {
   199	                    await LaunchAsync(name, spec, cloudInitPath, ct);
   200	                    await WaitForRunningAsync(name, ct);
   201	                }
   202	                // Stop the freshly-launched VM so we can mount (outside vm.launch scope).
   203	                var stop = await RunAsync([_opts.MultipassBinary, "stop", name], stdin: null, ct: ct);
   204	                if (stop.ExitCode != 0)
   205	                    throw new InvalidOperationException($"multipass stop (for mount) failed: {stop.Stderr}");
   206	                await WaitForStoppedAsync(name, ct);
   207	            }
   208	
   209	            // Apply native mounts while VM is Stopped, then start.
   210	            await using (var mountScope = await TimingScope.BeginAsync(
   211	                timingStore, timingItemId, timingPhase, "vm.mount", log: _log))
   212	            {
   213	                await ApplyMountsAsync(name, bindMounts, ct);
   214	            }
   215	
   216	            await using (var startScope = await TimingScope.BeginAsync(
   217	                timingStore, timingItemId, timingPhase, "vm.start", log: _log))
   218	            {
   219	                await StartAndWaitForRunningAsync(name, ct);
   220	            }
   221	
   222	            await TransferEnvAsync(name, spec.Environment, sandboxRoot, ct);
   223	            AuditLog.SandboxCreated(name, spec.Network.ProfileName);
   224	            // The exec wrapper is installed by cloud-init at boot
   225	            // (see BuildCloudInit's write_files); on the clone path it's
   226	            // already baked into the source VM's filesystem, so the clone
   227	            // inherits it. The codeybox-route systemd service runs on every
   228	            // boot in both paths.
   229	            _activeSandboxNames[name] = true;
   230	            // Invalidate the list cache so the next ListAllManagedAsync call reflects
   231	            // the newly created sandbox immediately rather than serving stale data.
   232	            _listCacheExpiry = DateTimeOffset.MinValue;
   233	            return new MultipassSandbox(name, sandboxRoot, spec, _opts, _log, timingStore, timingItemId, timingPhase,
   234	                onDisposed: n => { _activeSandboxNames.TryRemove(n, out _); _listCacheExpiry = DateTimeOffset.MinValue; },
   235	                runner: _runner);
   236	        }
   237	        catch
   238	        {
   239	            // Best-effort cleanup if launch / mount / transfer half-succeeded.
   240	            await TryDeleteVmAsync(name);
   241	            try { Directory.Delete(sandboxRoot, recursive: true); } catch { }
   242	            throw;
   243	        }
   244	    }
