   267	    /// <inheritdoc/>
   268	    public async Task DisposeLeakedAsync(string name, CancellationToken ct)
   269	    {
   270	        // Explicit allowlist before any filesystem or shell operation: VM names must
   271	        // be alphanumeric-and-hyphen only. This blocks path-traversal strings such as
   272	        // "codeybox-a/../../../sensitive" that start with the required prefix but
   273	        // would escape _stagingRoot once Path.Combine resolves them.
   274	        if (!IsValidSandboxName(name))
   275	            throw new ArgumentException($"Sandbox name '{name}' contains invalid characters (only [a-z0-9-] allowed).", nameof(name));
   276	
   277	        _log.LogInformation("SandboxLeakReaper: purging leaked VM {Name}", name);
   278	        var run = await RunAsync([_opts.MultipassBinary, "delete", "--purge", name], stdin: null, ct: ct);
   279	        if (run.ExitCode != 0)
   280	            throw new InvalidOperationException($"multipass delete --purge {name} failed (exit {run.ExitCode}): {run.Stderr}");
   281	        // Clean up staging dir if it still exists.
   282	        var stagingDir = Path.Combine(_stagingRoot, name);
   283	        try { if (Directory.Exists(stagingDir)) Directory.Delete(stagingDir, recursive: true); }
   284	        catch { /* best-effort */ }
   285	        // Remove from active set and invalidate cache.
   286	        _activeSandboxNames.TryRemove(name, out _);
   287	        _listCacheExpiry = DateTimeOffset.MinValue;
   288	    }
