   290	    private async Task<IReadOnlyList<ManagedSandboxInfo>> FetchManagedSandboxesAsync(CancellationToken ct)
   291	    {
   292	        var listRun = await RunAsync([_opts.MultipassBinary, "list", "--format", "json"], stdin: null, ct: ct);
   293	        if (listRun.ExitCode != 0)
   294	        {
   295	            _log.LogWarning("multipass list failed (exit {ExitCode}): {Stderr}", listRun.ExitCode, listRun.Stderr);
   296	            return [];
   297	        }
   298	
   299	        List<string> vmNames;
   300	        try
   301	        {
   302	            using var doc = JsonDocument.Parse(listRun.Stdout);
   303	            if (!doc.RootElement.TryGetProperty("list", out var listEl))
   304	                return [];
   305	
   306	            vmNames = [];
   307	            foreach (var item in listEl.EnumerateArray())
   308	            {
   309	                if (!item.TryGetProperty("name", out var nameEl)) continue;
   310	                var name = nameEl.GetString();
   311	                if (string.IsNullOrEmpty(name)) continue;
   312	                // Only sandboxes with the codeybox-* prefix (not cb-baseline-*).
   313	                if (!name.StartsWith("codeybox-", StringComparison.Ordinal)) continue;
   314	                vmNames.Add(name);
   315	            }
   316	        }
   317	        catch (JsonException ex)
   318	        {
   319	            _log.LogWarning(ex, "Failed to parse multipass list output");
   320	            return [];
   321	        }
   322	
   323	        if (vmNames.Count == 0) return [];
   324	
   325	        // Fetch disk usage for all discovered codeybox VMs in a single multipass info call.
   326	        var diskByName = await FetchDiskInfoAsync(vmNames, ct);
   327	
   328	        var infos = new List<ManagedSandboxInfo>(vmNames.Count);
   329	        foreach (var name in vmNames)
   330	        {
   331	            // Validate before using the name in Path.Combine, mirroring the check in
   332	            // DisposeLeakedAsync. Multipass enforces DNS-label naming so this should
   333	            // never fire, but we must not rely on an external tool's input validation
   334	            // for a filesystem path operation.
   335	            if (!IsValidSandboxName(name)) continue;
   336	
   337	            DateTimeOffset? createdAt = null;
   338	            var stagingDir = Path.Combine(_stagingRoot, name);
   339	            if (Directory.Exists(stagingDir))
   340	            {
   341	                var created = Directory.GetCreationTimeUtc(stagingDir);
   342	                if (created != DateTime.MinValue)
   343	                    createdAt = new DateTimeOffset(created, TimeSpan.Zero);
   344	            }
   345	            var isActive = _activeSandboxNames.ContainsKey(name);
   346	            var hasPreemptMarker = File.Exists(Path.Combine(stagingDir, ".codeybox-preempt"));
   347	            diskByName.TryGetValue(name, out var diskBytes);
   348	            infos.Add(new ManagedSandboxInfo(name, createdAt, diskBytes > 0 ? diskBytes : null, isActive, hasPreemptMarker));
   349	        }
   350	        return infos;
   351	    }
