   353	    /// <summary>
   354	    /// Runs <c>multipass info --format json</c> for the given VM names and returns
   355	    /// a map of VM name → disk-used bytes. Returns an empty dictionary on any failure
   356	    /// so that missing disk info degrades gracefully to null in the caller.
   357	    /// </summary>
   358	    private async Task<Dictionary<string, long>> FetchDiskInfoAsync(List<string> names, CancellationToken ct)
   359	    {
   360	        var argv = new List<string> { _opts.MultipassBinary, "info", "--format", "json" };
   361	        argv.AddRange(names);
   362	
   363	        var run = await RunAsync(argv, stdin: null, ct: ct);
   364	        if (run.ExitCode != 0)
   365	        {
   366	            _log.LogWarning("multipass info failed (exit {ExitCode}): {Stderr}", run.ExitCode, run.Stderr);
   367	            return [];
   368	        }
   369	
   370	        var result = new Dictionary<string, long>(StringComparer.Ordinal);
   371	        try
   372	        {
   373	            using var doc = JsonDocument.Parse(run.Stdout);
   374	            if (!doc.RootElement.TryGetProperty("info", out var infoEl))
   375	                return result;
   376	
   377	            foreach (var vmEntry in infoEl.EnumerateObject())
   378	            {
   379	                if (!vmEntry.Value.TryGetProperty("disks", out var disksEl)) continue;
   380	                long total = 0;
   381	                foreach (var diskEntry in disksEl.EnumerateObject())
   382	                {
   383	                    if (diskEntry.Value.TryGetProperty("used", out var usedEl) &&
   384	                        long.TryParse(usedEl.GetString(), out var used))
   385	                        total += used;
   386	                }
   387	                if (total > 0)
   388	                    result[vmEntry.Name] = total;
   389	            }
   390	        }
   391	        catch (JsonException ex)
   392	        {
   393	            _log.LogWarning(ex, "Failed to parse multipass info output; disk sizes will be omitted");
   394	        }
   395	        return result;
   396	    }
