   398	    private static bool IsValidSandboxName(string name)
   399	    {
   400	        // VM names must be alphanumeric-and-hyphen only (DNS-label style).
   401	        // This blocks path-traversal characters (/, ., \) before any filesystem use.
   402	        foreach (var c in name)
   403	        {
   404	            if (!char.IsAsciiLetterOrDigit(c) && c != '-')
   405	                return false;
   406	        }
   407	        return name.Length > 0;
   408	    }
