   410	    /// <summary>
   411	    /// Ensures the baseline VM for <paramref name="profileName"/> exists.
   412	    /// Bakes it on first call (~5-10 min: launch with cloud-init, install
   413	    /// agent CLIs and runtime, stop). Subsequent calls return the existing
   414	    /// baseline name.
   415	    ///
   416	    /// We bake one baseline per profile because <c>multipass clone</c>
   417	    /// inherits the source VM's network attachments — a baseline launched
   418	    /// with <c>--network cb-net</c> can only produce clones attached to
   419	    /// <c>cb-net</c>. Per-profile baselines also cleanly isolate "what each
   420	    /// profile installed" if profiles ever need different toolchains.
   421	    /// </summary>
   422	    private async Task<string> EnsureBaselineForProfileAsync(
   423	        string profileName,
   424	        SandboxProfileFlavor flavor,
   425	        CancellationToken ct)
   426	    {
   427	        var baselineProfile = flavor == SandboxProfileFlavor.Graphical
   428	            ? SandboxConventions.GraphicalNetworkProfile
   429	            : profileName;
   430	
   431	        if (!_opts.NetworkProfiles.TryGetValue(baselineProfile, out _))
   432	            throw new InvalidOperationException(
   433	                $"Network profile '{baselineProfile}' is not configured in MultipassSandboxOptions.NetworkProfiles. " +
   434	                $"Configured profiles: [{string.Join(", ", _opts.NetworkProfiles.Keys)}]");
   435	
   436	        var baselineName = _opts.BaselineNamePrefix + baselineProfile;
   437	        // multipass instance names cap at 24 chars; trim if a long profile
   438	        // name pushes us over. We use a STABLE hash (SHA-256, first 6 hex
   439	        // chars) for uniqueness so two long profile names don't collide.
   440	        // string.GetHashCode() can't be used here — it's randomised per
   441	        // process, so each orchestrator restart would produce a different
   442	        // baseline name and re-bake unnecessarily.
   443	        if (baselineName.Length > 24)
   444	        {
   445	            var bytes = System.Text.Encoding.UTF8.GetBytes(baselineName);
   446	            var hash = System.Security.Cryptography.SHA256.HashData(bytes);
   447	            var hex = Convert.ToHexString(hash.AsSpan(0, 3)).ToLowerInvariant();
   448	            baselineName = string.Concat(baselineName.AsSpan(0, 16), "-", hex);
   449	        }
   450	
   451	        var sem = GetBaselineLock(baselineName);
   452	        await sem.WaitAsync(ct);
   453	        try
   454	        {
   455	            if (await BaselineVmExistsAsync(baselineName, ct))
   456	                return baselineName;
   457	            await BakeBaselineAsync(baselineName, baselineProfile, flavor, ct);
   458	            return baselineName;
   459	        }
   460	        finally
   461	        {
   462	            sem.Release();
   463	        }
   464	    }
