   466	    private SemaphoreSlim GetBaselineLock(string baselineName)
   467	    {
   468	        lock (_baselineLocksGuard)
   469	        {
   470	            if (!_baselineLocks.TryGetValue(baselineName, out var sem))
   471	            {
   472	                sem = new SemaphoreSlim(1, 1);
   473	                _baselineLocks[baselineName] = sem;
   474	            }
   475	            return sem;
   476	        }
   477	    }
