   485	    private async Task BakeBaselineAsync(
   486	        string baselineName,
   487	        string profileName,
   488	        SandboxProfileFlavor flavor,
   489	        CancellationToken ct)
   490	    {
   491	        var bridge = _opts.NetworkProfiles[profileName];
   492	        _log.LogInformation(
   493	            "Baking Multipass baseline {Name} for profile {Profile} on bridge {Bridge} — one-time, ~5-10 minutes",
   494	            baselineName, profileName, bridge);
   495	
   496	        // Cloud-init for the baseline contains ONLY idempotent file-writes
   497	        // (exec wrapper, route systemd service). Caller-supplied install
   498	        // runcmds run via `multipass exec` AFTER launch instead. Why: when
   499	        // we `multipass clone` the baseline, multipass assigns the clone a
   500	        // fresh instance-id, so cloud-init thinks it's a brand-new instance
   501	        // and re-runs every per-instance module including runcmd. Putting
   502	        // installs in runcmd would mean re-running them on every clone —
   503	        // slow, and possibly disk-filling.
   504	        var cloudInit = BuildCloudInit(extraRuncmd: null, _opts.ExtraCloudInit, flavor);
   505	        var stagingDir = Path.Combine(_stagingRoot, "_baseline-" + baselineName);
   506	        Directory.CreateDirectory(stagingDir);
   507	        TryChmod0700(stagingDir);
   508	        var cloudInitPath = Path.Combine(stagingDir, "cloud-init.yaml");
   509	        await File.WriteAllTextAsync(cloudInitPath, cloudInit, ct);
   510	
   511	        var argv = new List<string> {
   512	            _opts.MultipassBinary, "launch", "--name", baselineName,
   513	            "--cloud-init", cloudInitPath,
   514	            "--network", $"name={bridge},mode=auto",
   515	            // Multipass defaults (5G disk / 1G RAM / 1 vCPU) are tight for
   516	            // a typical project install — language toolchain + agent CLI +
   517	            // any auditor binaries. Defaults here are operator-tunable via
   518	            // BaselineDiskGB / BaselineMemoryGB / BaselineCpus options;
   519	            // raise them if your install runs OOM or run out of disk
   520	            // mid-bake. qcow2 disks are sparse so unused disk space costs

Chunk ID: 306c51
Wall time: 0.0002 seconds
Process exited with code 0
Original token count: 7925
Output:
   521	            // nothing on the host until written.
   522	            "--disk", $"{_opts.BaselineDiskGB}G",
   523	            "--memory", $"{_opts.BaselineMemoryGB}G",
   524	            "--cpus", _opts.BaselineCpus.ToString(),
   525	        };
   526	        if (!string.IsNullOrWhiteSpace(_opts.DefaultImage))
   527	            argv.Add(_opts.DefaultImage);
   528	
   529	        try
   530	        {
   531	            var run = await RunAsync(argv, stdin: null, ct: ct);
   532	            if (run.ExitCode != 0)
   533	                throw new InvalidOperationException($"baseline launch failed: {run.Stderr}");
   534	
   535	            // Wait for the (now-minimal) cloud-init to finish — write_files
   536	            // and the route service install. Doesn't include the heavy
   537	            // installs, so should be fast.
   538	            await WaitForRunningAsync(baselineName, ct);
   539	
   540	            // Run the install commands now, via multipass exec under sudo.
   541	            // Each entry in ExtraRuncmd is a single shell command.
   542	            var installCommands = BuildFirstBootRuncmd(flavor);
   543	            for (var i = 0; i < installCommands.Count; i++)
   544	            {
   545	                var cmd = installCommands[i];
   546	                if (string.IsNullOrWhiteSpace(cmd)) continue;
   547	                _log.LogInformation("Baseline install step {N}/{Total}", i + 1, installCommands.Count);
   548	                var execRun = await RunAsync(
   549	                    [_opts.MultipassBinary, "exec", baselineName, "--", "sudo", "bash", "-c", cmd],
   550	                    stdin: null, ct: ct);
   551	                if (execRun.ExitCode != 0)
   552	                    throw new InvalidOperationException(
   553	                        $"baseline install step {i + 1} failed (exit {execRun.ExitCode}):\n" +
   554	                        $"stderr: {execRun.Stderr}\nstdout-tail: {(execRun.Stdout.Length > 1000 ? "…" + execRun.Stdout[^1000..] : execRun.Stdout)}");
   555	            }
   556	
   557	            // Stop the baseline so `multipass clone` can use it as a source
   558	            // (clone requires source stopped). Wait for the state to flip
   559	            // so a subsequent clone doesn't race a still-Stopping VM.
   560	            var stop = await RunAsync([_opts.MultipassBinary, "stop", baselineName], stdin: null, ct: ct);
   561	            if (stop.ExitCode != 0)
   562	                throw new InvalidOperationException($"baseline stop failed: {stop.Stderr}");
   563	            await WaitForStoppedAsync(baselineName, ct);
   564	
   565	            _log.LogInformation("Baseline {Name} baked and stopped, ready to clone", baselineName);
   566	        }
   567	        catch
   568	        {
   569	            // If bake half-succeeded, leave a partial baseline that the operator
   570	            // can `multipass delete --purge` and we'll re-bake. Don't auto-purge
   571	            // — losing partial install progress on transient errors is wasteful.
   572	            _log.LogError("Baseline bake for {Name} failed; you may need to `multipass delete --purge {PurgeTarget}` and retry", baselineName, baselineName);
   573	            throw;
   574	        }
   575	    }
