   577	    private async Task CloneFromBaselineAsync(string newName, string baselineName, CancellationToken ct)
   578	    {
   579	        // Defensive: ensure source is fully stopped before clone. Multipass
   580	        // clone requires it, but the baseline can get inadvertently
   581	        // restarted (e.g. operator runs `multipass exec` against it, which
   582	        // auto-starts stopped instances). Stop is idempotent — exits 0 if
   583	        // already stopped — and we wait for the state to flip because
   584	        // `multipass stop` returns when the request is queued.
   585	        await RunAsync([_opts.MultipassBinary, "stop", baselineName], stdin: null, ct: ct);
   586	        await WaitForStoppedAsync(baselineName, ct);
   587	
   588	        _log.LogInformation("Cloning {New} from baseline {Baseline}", newName, baselineName);
   589	        var clone = await RunAsync(
   590	            [_opts.MultipassBinary, "clone", baselineName, "--name", newName],
   591	            stdin: null, ct: ct);
   592	        if (clone.ExitCode != 0)
   593	            throw new InvalidOperationException($"multipass clone failed: {clone.Stderr}");
   594	
   595	        // NOTE: deliberately do NOT start the clone here. multipass clone
   596	        // creates the new VM in Stopped state, which is exactly what
   597	        // SetUpMountsAsync's `mount --type=native` requires. Starting now
   598	        // and stopping again later created a stop-state race where the
   599	        // mount could fire before multipassd had fully released the VM.
   600	    }
