   602	    internal IReadOnlyList<string> BuildLaunchArgv(string name, SandboxSpec spec, string cloudInitPath)
   603	    {
   604	        EnsureGraphicalProfileSelected(spec);
   605	        var argv = new List<string> { _opts.MultipassBinary, "launch", "--name", name };
   606	        if (spec.Limits.CpuCount is { } cpus) argv.AddRange(["--cpus", cpus.ToString()]);
   607	        if (spec.Limits.MemoryBytes is { } mem) argv.AddRange(["--memory", $"{mem / (1024 * 1024)}M"]);
   608	        if (spec.Limits.DiskBytes is { } disk) argv.AddRange(["--disk", $"{disk / (1024 * 1024)}M"]);
   609	        argv.AddRange(["--cloud-init", cloudInitPath]);
   610	
   611	        // Host-enforced egress profile. When the spec names a profile and
   612	        // the provider has a bridge mapped for it, attach the VM to that
   613	        // bridge as a SECONDARY network. The agent's only viable internet
   614	        // path is via this bridge — the operator's host-side nftables on
   615	        // the bridge enforces the allowlist; the agent cannot subvert it
   616	        // because the rules live in the host kernel, not the VM.
   617	        // Multipass's default mpqemubr0 is still attached (control plane
   618	        // needs it), but setup-host-networks.sh blocks all forwarding on
   619	        // it so it doesn't carry user traffic.
   620	        if (!string.IsNullOrWhiteSpace(spec.Network.ProfileName))
   621	        {
   622	            if (!_opts.NetworkProfiles.TryGetValue(spec.Network.ProfileName, out var bridge))
   623	                throw new InvalidOperationException(
   624	                    $"Network profile '{spec.Network.ProfileName}' is not configured in MultipassSandboxOptions.NetworkProfiles. " +
   625	                    $"Configured profiles: [{string.Join(", ", _opts.NetworkProfiles.Keys)}]. " +
   626	                    "Either add the profile to options or run setup-host-networks.sh and update appsettings.");
   627	            argv.AddRange(["--network", $"name={bridge},mode=auto"]);
   628	        }
   629	
   630	        // ImageReference: empty/null => multipass picks the default image.
   631	        if (!string.IsNullOrWhiteSpace(spec.ImageReference) && spec.ImageReference != "ignored")
   632	            argv.Add(spec.ImageReference);
   633	        else if (!string.IsNullOrWhiteSpace(_opts.DefaultImage))
   634	            argv.Add(_opts.DefaultImage);
   635	
   636	        return argv;
   637	    }
