   663	    private async Task WaitForRunningAsync(string name, CancellationToken ct)
   664	    {
   665	        // Two waits: first the VM enters "Running" state, then cloud-init
   666	        // finishes applying runcmd (which installs the exec wrapper and
   667	        // swaps the default route to the profile bridge). The exec
   668	        // wrapper is needed before any ExecAsync; the route swap is
   669	        // needed before any agent traffic actually leaves the VM via
   670	        // the host-enforced bridge.
   671	        var deadline = DateTime.UtcNow + TimeSpan.FromMinutes(3);
   672	        while (DateTime.UtcNow < deadline)
   673	        {
   674	            ct.ThrowIfCancellationRequested();
   675	            var info = await RunAsync([_opts.MultipassBinary, "info", name, "--format=csv"], stdin: null, ct: ct);
   676	            if (info.ExitCode == 0 && info.Stdout.Contains("Running", StringComparison.Ordinal))
   677	                break;
   678	            await Task.Delay(TimeSpan.FromSeconds(1), ct);
   679	        }
   680	        if (DateTime.UtcNow >= deadline)
   681	            throw new InvalidOperationException($"multipass VM {name} did not reach Running state within 3 minutes");
   682	
   683	        // `cloud-init status --wait` blocks until cloud-init has finished
   684	        // (success or fail). Exit code is non-zero on failure; we don't
   685	        // distinguish here because the post-launch verification (mount,
   686	        // exec) will surface concrete problems.
   687	        await RunAsync(
   688	            [_opts.MultipassBinary, "exec", name, "--", "cloud-init", "status", "--wait"],
   689	            stdin: null, ct: ct);
   690	    }
