   360	    private static byte[] BuildPng(
   361	        int width,
   362	        int height,
   363	        byte colorType,
   364	        byte[] decompressedScanlines,
   365	        byte bitDepth = 8,
   366	        byte interlace = 0,
   367	        byte[]? palette = null)
   368	    {
   369	        using var png = new MemoryStream();
   370	        png.Write([137, 80, 78, 71, 13, 10, 26, 10]);
   371	
   372	        var ihdr = new byte[13];
   373	        BinaryPrimitives.WriteInt32BigEndian(ihdr.AsSpan(0, 4), width);
   374	        BinaryPrimitives.WriteInt32BigEndian(ihdr.AsSpan(4, 4), height);
   375	        ihdr[8] = bitDepth;
   376	        ihdr[9] = colorType;
   377	        ihdr[10] = 0;
   378	        ihdr[11] = 0;
   379	        ihdr[12] = interlace;
   380	        WriteChunk(png, "IHDR", ihdr);
   381	
   382	        if (palette is not null)
   383	            WriteChunk(png, "PLTE", palette);
   384	
   385	        WriteChunk(png, "IDAT", CompressZlib(decompressedScanlines));
   386	        WriteChunk(png, "IEND", []);
   387	        return png.ToArray();
   388	    }
