   400	    private static void WriteChunk(Stream png, string type, byte[] data)
   401	    {
   402	        Span<byte> length = stackalloc byte[4];
   403	        BinaryPrimitives.WriteInt32BigEndian(length, data.Length);
   404	        png.Write(length);
   405	        png.Write(Encoding.ASCII.GetBytes(type));
   406	        png.Write(data);
   407	        png.Write([0, 0, 0, 0]);
   408	    }
