   407	        Func<ReleaseState, bool> predicate,
   408	        int timeoutSeconds)
   409	    {
   410	        var deadline = DateTimeOffset.UtcNow.AddSeconds(timeoutSeconds);
   411	        while (DateTimeOffset.UtcNow < deadline)
   412	        {
   413	            var r = await _releaseStore.GetAsync(id);
   414	            if (r is not null && predicate(r.State))
   415	                return r.State;
   416	            await Task.Delay(20);
