   291	        ISandbox sandbox,
   292	        Func<string, bool> predicate,
   293	        TimeSpan timeout)
   294	    {
   295	        var deadline = DateTimeOffset.UtcNow + timeout;
   296	        string log = "";
   297	        while (DateTimeOffset.UtcNow < deadline)
   298	        {
   299	            var read = await sandbox.ExecAsync(new SandboxExec
   300	            {
