   302	            });
   303	            Assert.True(read.Success, read.Stderr);
   304	            log = read.Stdout;
   305	            if (predicate(log))
   306	                return log;
   307	            await Task.Delay(TimeSpan.FromMilliseconds(250));
   308	        }
   309	
   310	        return log;
   311	    }
